const errorData = $input.first().json;

const execution = errorData.execution || {};
const execError = execution.error || {};
const workflowInfo = errorData.workflow || {};
const execContext = execution.executionContext || {};

const workflowName = workflowInfo.name || 'Unknown Workflow';
const workflowId = workflowInfo.id || 'N/A';
const executionId = execution.id || 'N/A';
const executionUrl = execution.url || 'N/A';

const errorNodeInfo = execError.node || {};
const errorNode = errorNodeInfo.name || execution.lastNodeExecuted || 'Unknown Node';
const errorNodeType = errorNodeInfo.type || 'N/A';
const errorMessage = execError.message || 'No error message';
const errorDescription = execError.description || '';
const errorStack = execError.stack || '';

const timestamp = execContext.establishedAt
  ? new Date(execContext.establishedAt).toISOString()
  : new Date().toISOString();

// Throttle: the same error (workflow + node + message) is sent to Telegram at
// most once per THROTTLE_MS. Repeats are counted and reported on the next send.
const THROTTLE_MS = 10 * 60 * 1000;
const staticData = $getWorkflowStaticData('global');
const throttle = staticData.errorThrottle || (staticData.errorThrottle = {});
const now = Date.now();
for (const [k, v] of Object.entries(throttle)) {
  if (now - v.lastSent > THROTTLE_MS * 6) delete throttle[k];
}
const throttleKey = [workflowId, errorNode, String(errorMessage).slice(0, 200)].join('|');
const prev = throttle[throttleKey];
if (prev && now - prev.lastSent < THROTTLE_MS) {
  prev.suppressed = (prev.suppressed || 0) + 1;
  return [];
}
const suppressedCount = prev ? prev.suppressed || 0 : 0;
throttle[throttleKey] = { lastSent: now, suppressed: 0 };

// Escape HTML entities to prevent Telegram parse errors
// Telegram HTML parser is strict — <anonymous> in stack traces breaks it
const escapeHtml = (str) => {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
};

const truncate = (str, maxLen = 3000) => {
  if (!str) return 'N/A';
  const s = String(str);
  return s.length > maxLen ? s.substring(0, maxLen) + '...' : s;
};

const safeMessage = escapeHtml(truncate(errorMessage, 1000));
const safeDescription = escapeHtml(truncate(errorDescription, 500));
const safeStack = escapeHtml(truncate(errorStack, 2000));
const safeWorkflowName = escapeHtml(workflowName);
const safeErrorNode = escapeHtml(errorNode);
const safeErrorNodeType = escapeHtml(errorNodeType);
const safeMode = escapeHtml(execution.mode || 'N/A');
const safeLastNode = escapeHtml(execution.lastNodeExecuted || '');

const message = `
🔴 <b>Workflow Error Alert</b>

📋 <b>Workflow:</b> ${safeWorkflowName}
🆔 <b>Workflow ID:</b> <code>${escapeHtml(workflowId)}</code>
⏰ <b>Time:</b> ${new Date(timestamp).toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' })}

⚠️ <b>Error Node:</b> ${safeErrorNode}
📌 <b>Node Type:</b> ${safeErrorNodeType}
❌ <b>Error:</b> ${safeDescription}
💬 <b>Message:</b>
<code>${safeMessage}</code>

🔗 <b>Execution:</b> <a href="${executionUrl}">${escapeHtml(executionId)}</a>
🔍 <b>Mode:</b> ${safeMode}
${safeLastNode ? '🏃 <b>Last Node:</b> ' + safeLastNode : ''}
${suppressedCount ? '🔁 <b>Repeated:</b> ' + suppressedCount + ' more time(s) since the last alert' : ''}

📝 <b>Stack Trace:</b>
<code>${safeStack}</code>
`.trim();

return [{
  json: {
    workflowName,
    workflowId,
    executionId,
    executionUrl,
    errorNode,
    errorNodeType,
    errorMessage: truncate(errorMessage, 500),
    errorDescription,
    timestamp,
    message
  }
}];

// Audit log for the notification
const data = $input.first().json;

const logEntry = {
  workflow_name: data.workflowName,
  workflow_id: data.workflowId,
  execution_id: data.executionId,
  error_node: data.errorNode,
  error_message: data.errorMessage,
  notified_at: data.timestamp
};

console.log('Error notification sent:', JSON.stringify(logEntry, null, 2));

return [{ json: { ...data, logged: true, logEntry } }];
